  pings: { chance: 0.3, gap: 3, maxPending: 3 },

  // ── 日历：每天的邀约模板。代码每天抽 1~3 条，纯代码，不花 token ──
  //   by：'talent' = 旗下艺人发来的；其余是工作人员的名字（要和上面 staff 的键一致）
