        segs.forEach(function (sg) { var km = sg.match(/^(档位|类型|场景|她是|试听|标题)\s*[:：]\s*(.*)$/); if (km) { hdr[SG_HDR[km[1]]] = km[2].trim(); hit = true; } });
        if (hit) { seen = true; return; }
