    var hdr = { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + cfg.key };
    var routes = [
      { path: '/compat/v1/audio/speech', body: { model: fm.indexOf('/') >= 0 ? fm : 'fish-audio/' + fm, input: input, voice: fishId, response_format: 'mp3',
          provider: { options: { 'fish-audio': { prosody: { speed: spd }, latency: 'balanced' } } } } },
      { path: '/v1/audio/speech', body: { model: fm, input: input, voice: fishId, response_format: 'mp3', speed: spd } },   // 自架中转只开 OpenAI 形状时
    ];
