    if (r.status === 429) throw new Error('Fish 限流了，等一会儿再点');
    if (!r.ok) { var d = ''; try { d = (await r.text()).slice(0, 120); } catch (e) {} throw new Error('Fish 没念出来（HTTP ' + r.status + '）' + (d ? '：' + d : '')); }
