      var p = pend.length === 1 ? buildPrompt(pend[0], script) : buildBatchPrompt(pend, script), raw = null, err = null;
      try { raw = await genAsk(p, attempt ? (pend.length === 1 ? RETRY_NOTE : RETRY_NOTE_BATCH) : '', 'shacho-batch-' + pend[0].id + '-' + attempt); }
      catch (e) { err = e; }
