    '#shacho-panel .sh-cd .dots i.w{background:var(--sh-ink);}',
    '#shacho-panel .sh-cd.today .dots i{background:var(--sh-accent-ink);}',
    '#shacho-panel .sh-cd.today .dots i.p{background:transparent;}',
    '#shacho-panel .sh-legend{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12px;color:var(--sh-faint);margin-top:10px;}',
    '#shacho-panel .sh-legend i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--sh-accent);margin-right:5px;vertical-align:1px;}',
    '#shacho-panel .sh-legend i.p{background:transparent;border:1px solid var(--sh-faint);}',
    '#shacho-panel .sh-legend i.w{background:var(--sh-ink);}',
    '#shacho-panel .sh-dayh{font-size:17px;font-weight:800;margin:0 0 10px;}',
    '#shacho-panel .sh-dayh small{font-size:13px;font-weight:600;color:var(--sh-faint);margin-left:8px;}',
    '#shacho-panel .sh-invs{display:flex;flex-direction:column;gap:10px;}',
