    '#shacho-panel .sh-inv.s-ignored,#shacho-panel .sh-inv.s-missed{border-left-color:var(--sh-line);opacity:.72;}',
    '#shacho-panel .sh-inv.s-went{border-left-color:var(--sh-ink);}',
    '#shacho-panel .sh-inv .top{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;}',
