    '#shacho-panel .sh-inv .st.pending{color:var(--sh-accent);}',
    '#shacho-panel .sh-inv p{margin:6px 0 4px;font-size:14.5px;line-height:1.7;color:var(--sh-ink);}',
    '#shacho-panel .sh-inv .wh{font-size:13px;color:var(--sh-sub);}',
    '#shacho-panel .sh-inv .owl{font-size:12px;color:var(--sh-faint);margin-top:4px;}',
    '#shacho-panel .sh-inv .acts{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;}',
    '#shacho-panel .sh-inv .acts .sh-btn{min-height:40px;font-size:14px;padding:0 16px;}',

    /* 排练室 */
    '#shacho-panel .sh-rh{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:start;}',
    '#shacho-panel .sh-box{background:var(--sh-card);border:1px solid var(--sh-line);border-radius:12px;padding:16px 18px;margin-bottom:16px;}',
    '#shacho-panel .sh-box textarea,#shacho-panel .sh-box input.sh-in{display:block;width:100%;padding:10px 12px;border:1px solid var(--sh-line);border-radius:8px;background:var(--sh-input);color:var(--sh-ink);font-size:15px;line-height:1.6;resize:vertical;}',
    '#shacho-panel .sh-box textarea{min-height:110px;}',
    '#shacho-panel .sh-box textarea.long{min-height:200px;}',
    '#shacho-panel .sh-box input.sh-in{min-height:44px;}',
    '#shacho-panel .sh-hint{font-size:12.5px;color:var(--sh-faint);margin-top:6px;}',
    '#shacho-panel .sh-rhgo{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px;}',
    '#shacho-panel .sh-takes{display:flex;flex-direction:column;gap:12px;}',
    '#shacho-panel .sh-take{background:var(--sh-card);border:1px solid var(--sh-line);border-radius:10px;padding:12px 14px;}',
    '#shacho-panel .sh-take.last{border-color:var(--sh-accent);}',
