    '#shacho-panel .sh-take .rd div{padding:1px 0;}',
    '#shacho-panel .sh-take .nt{font-size:13.5px;color:var(--sh-sub);}',
    '#shacho-panel .sh-take .dr{display:inline-block;font-size:12px;padding:1px 8px;border-radius:999px;background:var(--sh-accent-soft);color:var(--sh-accent);margin-top:2px;}',

    /* 即将开放 */
    '#shacho-panel .sh-soon{padding:60px 24px;text-align:center;border:1px dashed var(--sh-line);border-radius:12px;color:var(--sh-sub);}',
    '#shacho-panel .sh-soon b{display:block;font-size:22px;color:var(--sh-ink);margin-bottom:8px;}',

    /* 弹层 */
    '#shacho-panel .sh-modal{position:absolute;inset:0;background:rgba(10,8,6,.45);display:flex;align-items:center;justify-content:center;padding:16px;z-index:5;}',
    '#shacho-panel .sh-dialog{width:min(440px,100%);background:var(--sh-card);color:var(--sh-ink);border-radius:14px;padding:22px 22px 18px;box-shadow:var(--sh-shadow);}',
    '#shacho-panel .sh-dialog h3{margin:0 0 6px;font-size:19px;font-weight:800;color:var(--sh-ink);}',
    '#shacho-panel .sh-dialog p{margin:0 0 14px;font-size:14px;color:var(--sh-sub);line-height:1.65;}',
    '#shacho-panel .sh-dialog input{display:block;width:100%;min-height:50px;padding:0 14px;border:1px solid var(--sh-line);border-radius:10px;background:var(--sh-input);color:var(--sh-ink);font-size:18px;}',
    '#shacho-panel .sh-dialog .err{color:var(--sh-accent);font-size:13px;min-height:20px;margin-top:6px;}',
    '#shacho-panel .sh-dialog .row{display:flex;gap:10px;justify-content:flex-end;margin-top:12px;}',

    /* 顶栏：事务所名 + 账上余额 */
    '#shacho-panel .sh-logo .ag{font-size:12px;letter-spacing:.12em;color:var(--sh-sub);font-weight:700;}',
    '#shacho-panel .sh-money{flex:none;min-height:36px;padding:0 12px;border-radius:999px;border:1px solid var(--sh-line);background:var(--sh-paper);color:var(--sh-ink);font-size:13.5px;font-weight:700;cursor:pointer;white-space:nowrap;font-variant-numeric:tabular-nums;}',
    '#shacho-panel .sh-money:hover{border-color:var(--sh-ink);}',
    '#shacho-panel .sh-money .cmp{display:none;}',
    '#shacho-panel .sh-money.neg{color:#c62828;border-color:#c62828;background:rgba(198,40,40,.08);}',
    '#shacho-panel.night .sh-money.neg{color:#ff6b6b;border-color:#ff6b6b;background:rgba(255,107,107,.12);}',
    '#shacho-panel .sh-broke{margin:0 0 16px;padding:10px 14px;border-radius:10px;background:rgba(198,40,40,.1);color:#c62828;font-weight:800;font-size:15px;}',
    '#shacho-panel.night .sh-broke{color:#ff7b7b;background:rgba(255,107,107,.13);}',
    /* 开局填表 */
    '#shacho-panel.setup{grid-template-columns:1fr;grid-template-areas:"head" "main";}',
    '#shacho-panel .sh-setup{max-width:520px;margin:20px auto 0;}',
    '#shacho-panel .sh-say{font-size:14.5px;color:var(--sh-sub);line-height:1.75;margin:0 0 14px;}',
    /* 弹层：宽的、能滚的 */
    '#shacho-panel .sh-dialog{max-height:calc(100% - 8px);overflow-y:auto;overscroll-behavior:contain;}',
    '#shacho-panel .sh-dialog.wide{width:min(600px,100%);}',
    '#shacho-panel .sh-dialog h3 small{display:block;font-size:12.5px;font-weight:600;color:var(--sh-faint);margin:4px 0 0;}',
    '#shacho-panel .sh-dialog .sh-label{margin-bottom:6px;}',
    '#shacho-panel .sh-fee{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin:-4px 0 14px;padding:10px 12px;border-radius:10px;background:var(--sh-accent-soft);font-size:13px;color:var(--sh-sub);}',
    '#shacho-panel .sh-fee b{font-size:18px;color:var(--sh-ink);}',
    '#shacho-panel .sh-online{font-size:12.5px;color:var(--sh-faint);margin-top:4px;}',
    /* 账本 */
    '#shacho-panel .sh-bal{display:flex;align-items:baseline;gap:10px;margin:6px 0 8px;}',
    '#shacho-panel .sh-pay{width:100%;border-collapse:collapse;margin:8px 0;font-size:14px;}',
    '#shacho-panel .sh-pay td{padding:5px 2px;border-bottom:1px solid var(--sh-line);vertical-align:top;}',
    '#shacho-panel .sh-pay td.amt{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--sh-accent);}',
    '#shacho-panel .sh-pay tr.nt td{border-bottom:0;padding-top:0;font-size:12px;color:var(--sh-faint);}',
    '#shacho-panel .sh-pay tr.tot td{font-weight:800;font-size:16px;border-bottom:0;padding-top:9px;}',
    '#shacho-panel .sh-payroll .warn{color:var(--sh-accent);font-weight:700;}',
    '#shacho-panel input.sh-sign{font-family:"Ma Shan Zheng","STXingkai","华文行楷","Kaiti SC","KaiTi",cursive;font-size:26px;text-align:center;border:0;border-bottom:2px solid var(--sh-ink);background:transparent;width:100%;padding:6px 0;}',
    '#shacho-panel .sh-bal span{font-size:13px;color:var(--sh-faint);}',
    '#shacho-panel .sh-bal b{font-size:28px;font-weight:800;font-variant-numeric:tabular-nums;}',
    '#shacho-panel .sh-bal.neg b{color:#c62828;}',
    '#shacho-panel.night .sh-bal.neg b{color:#ff6b6b;}',
    '#shacho-panel .sh-loan{border:1px solid var(--sh-line);border-radius:10px;padding:12px 14px;margin:0 0 14px;}',
    '#shacho-panel .sh-loan p{margin:0 0 10px;}',
    '#shacho-panel .sh-loan .sh-say{margin:10px 0 0;font-size:13.5px;}',
